target.css:
:root {
  --paper: #fffdf8;
  --ink: #25233a;
  --muted: #716d83;
  --line: #ded9e8;
  --violet: #6752a7;
  --lavender: #eeeafd;
  --gold: #efb84e;
  --coral: #e77768;
  --mint: #d9f0e7;
  --white: #ffffff;
}

* {
  box-sizing: border-box;
}

.reading-card {
  width: 500px;
  padding: 14px;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header,
.title-group,
.attendee-row,
.card-footer {
  display: flex;
  align-items: center;
}

.card-header {
  justify-content: space-between;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.title-group {
  gap: 9px;
}

.emblem {
  display: grid;
  width: 31px;
  height: 31px;
  place-items: center;
  color: var(--white);
  background: var(--violet);
  border-radius: 10px 10px 4px 10px;
  font-size: 19px;
  font-weight: 700;
}

.eyebrow,
.section-label,
.book-author {
  margin: 0;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1 {
  margin: 1px 0 0;
  font-size: 19px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.date-pill,
.page-chip,
.status {
  display: inline-block;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.date-pill {
  padding: 6px 8px;
  color: var(--violet);
  background: var(--lavender);
  border-radius: 7px;
}

.content-grid {
  display: grid;
  grid-template-columns: 1.05fr 1.35fr;
  gap: 14px;
  padding: 13px 0;
}

.book-panel {
  display: flex;
  gap: 10px;
  margin: 0;
  padding: 10px;
  background: var(--lavender);
  border-radius: 12px;
}

.book-cover {
  display: flex;
  flex: 0 0 62px;
  min-height: 104px;
  align-items: flex-end;
  padding: 7px;
  color: var(--paper);
  background: var(--ink);
  border: 3px solid var(--gold);
  border-radius: 4px 10px 10px 4px;
}

.book-cover span {
  font-size: 9px;
  font-weight: 800;
  line-height: 1.06;
  letter-spacing: 0.06em;
}

figcaption {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  justify-content: center;
  min-width: 0;
}

.book-title {
  margin: 0 0 6px;
  font-size: 14px;
  font-weight: 800;
  line-height: 1.08;
  letter-spacing: -0.025em;
}

.book-author {
  line-height: 1.3;
}

.page-chip {
  margin-top: 10px;
  padding: 4px 5px;
  color: var(--ink);
  background: var(--mint);
  border-radius: 4px;
}

.session-panel {
  min-width: 0;
  padding: 3px 0;
}

.section-label {
  margin-bottom: 7px;
}

.progress-list {
  display: grid;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.progress-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  padding: 5px 6px;
  border: 1px solid var(--line);
  border-radius: 7px;
}

.chapter {
  overflow: hidden;
  font-size: 11px;
  font-weight: 700;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.status {
  flex: 0 0 auto;
  padding: 3px 5px;
  color: var(--muted);
  background: var(--paper);
  border-radius: 4px;
}

.status.done {
  color: var(--violet);
  background: var(--lavender);
}

.status.live {
  color: var(--white);
  background: var(--coral);
}

.attendee-row {
  justify-content: space-between;
  margin-top: 8px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.avatars {
  display: flex;
  padding-left: 5px;
}

.avatar {
  display: grid;
  width: 20px;
  height: 20px;
  margin-left: -5px;
  place-items: center;
  color: var(--white);
  border: 2px solid var(--paper);
  border-radius: 50%;
  font-size: 8px;
  font-weight: 800;
}

.avatar.one { background: var(--violet); }
.avatar.two { background: var(--gold); }
.avatar.three { background: var(--coral); }
.avatar.more {
  color: var(--ink);
  background: var(--mint);
}

.card-footer {
  justify-content: space-between;
  padding-top: 10px;
  border-top: 1px solid var(--line);
}

.room {
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
}

.room b {
  color: var(--coral);
  font-size: 12px;
}

button {
  padding: 8px 10px;
  color: var(--white);
  background: var(--violet);
  border: 0;
  border-radius: 8px;
  font-size: 11px;
  font-weight: 800;
}

